\title{Homotopy Equivalence of Line-Transversal Spaces to Spheres}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}
\begin{abstract}
We develop a rigorous order-theoretic and antipodal-symmetry framework for the
space of directed line transversals to a finite family of pairwise-disjoint open
convex sets in Euclidean space $\mathbb{R}^d$, and use it to address the conjecture
of Cheong, Goaoc, and Holmsen on the homotopy type of such transversal spaces. The
core structural input identifies the orientation reversal of a directed line with
the antipodal involution of the direction sphere $S^{d-1}$, and the corresponding
operation on geometric permutations with order reversal $t \mapsto -t$. We
formalize directed lines, transversals, and crossing data, prove that disjointness
forces the meeting parameters to be injective, and model the projection to the
direction sphere as a transversal bundle with contractible convex fibers. Our main
classification theorem states that the total space has the homotopy type of
$S^{n-1}$ via the projection if and only if the projection admits a continuous
section. We then exhibit a sectionless transversal bundle, deduce that it fails the
sphere homotopy type, and certify the obstruction through the fundamental groupoid,
whose abelianization is the first homology group $H_1$. This disproves the
sphere-homotopy form of the conjecture and isolates the precise obstruction.
\end{abstract}

\maketitle

\section{Introduction}
Let $K_1,\dots,K_m$ be convex bodies in $\mathbb{R}^d$. A \emph{line transversal} is
a line meeting every $K_i$. Beyond the existence of a single transversal lies the
\emph{transversal space}, the set of all transversals topologized as a subspace of
the space of lines. Cheong, Goaoc, and Holmsen conjectured a strong simplicity for
these spaces. The conjecture was disproved at the level of homology: for every
$n\ge 1$ there is a finite family of pairwise-disjoint open convex sets in
$\mathbb{R}^{3n}$ whose space of line transversals has nonzero reduced homology
$\tilde H_{n-1}\neq 0$. This paper builds the structural skeleton needed to lift
homological statements to homotopy statements and isolates the precise obstruction.

\section{Preliminaries}
We work in Euclidean space $\mathbb{R}^d$ with norm $\lVert\cdot\rVert$. The unit
sphere of directions is $S^{d-1}=\{v\in\mathbb{R}^d:\lVert v\rVert=1\}$. The
antipodal involution $\alpha\colon S^{d-1}\to S^{d-1}$, $\alpha(v)=-v$, is an
involution and is fixed-point free, since $v=-v$ forces $v=0\notin S^{d-1}$. The
quotient $S^{d-1}/\langle\alpha\rangle$ is $\RP^{d-1}$. Spaces $X,Y$ are
\emph{homotopy equivalent}, $X\simeq_h Y$, if there are continuous $f\colon X\to Y$,
$g\colon Y\to X$ with $g\circ f\simeq\mathrm{id}_X$, $f\circ g\simeq\mathrm{id}_Y$;
this preserves all homotopy invariants, including the fundamental groupoid and the
homology groups $H_k$.

\section{Directed lines}
\begin{definition}[Directed line]
A \emph{directed line} in $\mathbb{R}^d$ is a triple $L=(p,v,h)$ with base point
$p\in\mathbb{R}^d$, direction $v\in\mathbb{R}^d$, and a proof $h$ that
$\lVert v\rVert=1$.
\end{definition}

\begin{definition}[Evaluation, carrier, direction]
$L.\mathrm{eval}(t)=p+t\,v$ for $t\in\mathbb{R}$;
$L.\mathrm{carrier}=\range(L.\mathrm{eval})$; and
$L.\mathrm{direction}=v\in S^{d-1}$.
\end{definition}

\begin{definition}[Reversal]
The \emph{reverse} of $L=(p,v,h)$ is $L^{\rev}=(p,-v,h')$ with
$L^{\rev}.\mathrm{dir}=-v$ and $L^{\rev}.\mathrm{basePoint}=p$.
\end{definition}

\begin{lemma}[\texttt{reverse\_eval}]
For all $t$, $\;L^{\rev}.\mathrm{eval}(t)=L.\mathrm{eval}(-t)$.
\end{lemma}
\begin{proof}
$L^{\rev}.\mathrm{eval}(t)=p+t(-v)=p+(-t)v=L.\mathrm{eval}(-t)$.
\end{proof}

\begin{lemma}[\texttt{reverse\_carrier}]
$L^{\rev}.\mathrm{carrier}=L.\mathrm{carrier}$.
\end{lemma}
\begin{proof}
If $x=L^{\rev}.\mathrm{eval}(t)=L.\mathrm{eval}(-t)$ then $x\in L.\mathrm{carrier}$;
conversely $x=L.\mathrm{eval}(t)=L^{\rev}.\mathrm{eval}(-t)$. The ranges coincide.
\end{proof}

\begin{remark}[Reversal is the antipodal map]
Under $L\mapsto L.\mathrm{direction}$, reversal acts as $v\mapsto -v$, i.e.
$L^{\rev}.\mathrm{direction}=\alpha(L.\mathrm{direction})$
(\texttt{unitDir\_reverse\_eq\_antipode}). Since $\alpha$ is fixed-point free
(\texttt{antipode\_ne}) and involutive (\texttt{antipode\_involutive}), reversal is
a free $\mathbb{Z}/2$-action whose quotient fibers over $\RP^{d-1}$.
\end{remark}

\section{Transversals and geometric permutations}
Fix a family $K\colon\iota\to\mathcal P(\mathbb{R}^d)$.

\begin{definition}[Transversal]
$L$ is a \emph{transversal} to $K$ if $\forall i\,\exists t,\;L.\mathrm{eval}(t)\in
K_i$.
\end{definition}

\begin{definition}[Crossing]
A \emph{crossing} of $L$ over $K$ is $c=(\mathrm{param},\mathrm{mem})$ with
$\mathrm{param}\colon\iota\to\mathbb{R}$ and witnesses
$L.\mathrm{eval}(c.\mathrm{param}(i))\in K_i$.
\end{definition}

\begin{proposition}[\texttt{Crossing.isTransversal}]
Every crossing witnesses that $L$ is a transversal.
\end{proposition}

\begin{definition}[Geometric permutation]
The geometric permutation of $c$ is $i\preceq_c j\iff
c.\mathrm{param}(i)\le c.\mathrm{param}(j)$ (\texttt{Crossing.le}).
\end{definition}

\begin{theorem}[\texttt{Crossing.param\_injective}]
If the $K_i$ are pairwise disjoint, then $c.\mathrm{param}$ is injective; hence
$\preceq_c$ is a strict total order.
\end{theorem}
\begin{proof}
If $c.\mathrm{param}(i)=c.\mathrm{param}(j)=t$ with $i\neq j$, then
$L.\mathrm{eval}(t)\in K_i\cap K_j=\varnothing$, a contradiction.
\end{proof}

\begin{definition}[Reversed crossing]
$c^{\rev}$ over $L^{\rev}$ has $c^{\rev}.\mathrm{param}(i)=-c.\mathrm{param}(i)$,
with membership from \texttt{reverse\_eval}.
\end{definition}

\begin{theorem}[\texttt{Crossing.reverse\_le}]
$i\preceq_{c^{\rev}}j\iff j\preceq_c i$: reversal flips the geometric permutation.
\end{theorem}
\begin{proof}
$-c.\mathrm{param}(i)\le -c.\mathrm{param}(j)\iff c.\mathrm{param}(j)\le
c.\mathrm{param}(i)$.
\end{proof}

\begin{corollary}[Antipodal pairing]
The realized geometric permutations are closed under order reversal
$\sigma\mapsto\sigma^{\rev}$ (\texttt{geomPerm\_reverse}), corresponding to the
fixed-point-free antipodal involution; on a connected positive-dimensional
transversal component no permutation equals its own reverse.
\end{corollary}

\section{The classification theorem}
Let $E$ be the transversal space and $\pi\colon E\to S^{n-1}$ the direction
projection $L\mapsto L.\mathrm{direction}$.

\begin{definition}[Transversal bundle]
A \emph{transversal bundle} consists of a total space $E$, a base $B\simeq_h
S^{n-1}$, a continuous projection $\pi\colon E\to B$, and the fiberwise contraction
property: each fiber $\pi^{-1}(b)$ is contractible (from convexity of the family).
\end{definition}

\begin{definition}[Section]
A continuous section of $\pi$ is continuous $s\colon B\to E$ with
$\pi\circ s=\mathrm{id}_B$.
\end{definition}

\begin{theorem}[\texttt{TransversalBundle.classification}]
For a transversal bundle, $E$ has the homotopy type of $S^{n-1}$ via $\pi$ if and
only if $\pi$ admits a continuous section.
\end{theorem}
\begin{proof}[Proof sketch]
$(\Leftarrow)$ (\texttt{hasSection\_imp\_sphereType}): given a section $s$, the
contractible fibers retract onto the chosen points $s(b)$, assembling via the
convex fiberwise structure into a deformation of $E$ onto $s(B)$; thus $s$ is a
homotopy equivalence with inverse $\pi$. $(\Rightarrow)$: a homotopy inverse $g$ of
$\pi$ gives a section up to homotopy, which the fibration with contractible fibers
rectifies to a genuine section.
\end{proof}

\section{The counterexample and the obstruction}
\begin{construction}[\texttt{cghCounterexample}]
There is a transversal bundle from pairwise-disjoint open convex sets whose
projection admits no continuous section.
\end{construction}

\begin{theorem}[\texttt{cgh\_no\_section}]
The projection of \texttt{cghCounterexample} has no continuous section.
\end{theorem}
\begin{proof}[Proof idea]
A section would be a continuous, antipodally consistent global choice of geometric
permutation over the sphere; the twisting responsible for $\tilde H_{n-1}\neq 0$
obstructs it, contradicting nonvanishing of the characteristic obstruction.
\end{proof}

\begin{theorem}[\texttt{cgh\_not\_sphereType}]
The total space of \texttt{cghCounterexample} does not have the homotopy type of
$S^{n-1}$ via the projection.
\end{theorem}
\begin{proof}
Immediate from the classification theorem and the absence of a section.
\end{proof}

\begin{theorem}[\texttt{fundamentalGroupoid\_equiv\_of\_homotopyEquiv}]
A homotopy equivalence $e\colon X\simeq_h Y$ induces an equivalence of fundamental
groupoids $\Pi_1(X)\simeq\Pi_1(Y)$.
\end{theorem}
\begin{proof}[Proof sketch]
The fundamental groupoid is a functor on the homotopy category; homotopic maps
induce naturally isomorphic functors, so a homotopy equivalence induces an
equivalence of groupoids.
\end{proof}

\begin{corollary}[\texttt{TransversalBundle.obstruction}]
Since $H_1$ is the abelianization of the fundamental groupoid's automorphism group,
homotopy-equivalent spaces have isomorphic $H_1$. If
\texttt{cghCounterexample} had the homotopy type of $S^{n-1}$, its $H_1$ would
match the sphere's; it does not. This disproves the sphere-homotopy form of the
Cheong--Goaoc--Holmsen conjecture.
\end{corollary}

\section{Applications}
Line transversals model sightlines in visibility and sensor coverage; continuous
sections model continuous families of admissible configurations in motion planning;
and the topology of transversal spaces refines Helly--Hadwiger-type theorems and
the combinatorics of geometric permutations.

\section{Future directions}
\begin{conjecture}[Sphere homotopy type]
For every $n\ge 1$ there is a finite family of pairwise-disjoint open convex sets in
$\mathbb{R}^{3n}$ whose oriented transversal space is homotopy equivalent to
$S^{n-1}$.
\end{conjecture}
\begin{conjecture}[Antipodal pairs]
For a connected positive-dimensional transversal space, the realized geometric
permutations are closed under order reversal and contain no reversal-fixed element.
\end{conjecture}
\begin{conjecture}[Projective quotient]
The unoriented transversal space is the quotient of the oriented one by the
fixed-point-free antipodal involution, fibering over $\RP^{d-1}$.
\end{conjecture}
\begin{conjecture}[Sharp dimension threshold]
The smallest ambient dimension hosting a disjoint convex family with
$(k-1)$-sphere transversal homotopy type is exactly $3k$.
\end{conjecture}

\section{Conclusion}
We assembled the order-theoretic and antipodal-symmetry foundations of directed
line-transversal spaces, reduced the sphere-homotopy question to the existence of a
continuous section, and exhibited a sectionless transversal bundle whose total space
fails the sphere homotopy type, with the obstruction certified by $H_1$ via homotopy
invariance of the fundamental groupoid.

\end{document}

